// Content with portions generated by generative AI platform
package org.eclipse.kura.core.data.store;

import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.doThrow;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import org.eclipse.kura.KuraStoreException;
import org.eclipse.kura.message.store.provider.MessageStore;
import org.junit.Test;

public class HouseKeeperTaskTest {

    private static final int PURGE_AGE = 60;

    private final MessageStoreState storeState = mock(MessageStoreState.class);
    private final MessageStore messageStore = mock(MessageStore.class);
    private final HouseKeeperTask task = new HouseKeeperTask(this.storeState, PURGE_AGE);
    private Throwable propagatedThrowable;

    /*
     * Scenarios
     */

    @Test
    public void purgesStaleMessages() throws KuraStoreException {
        givenMessageStoreAvailable();

        whenTaskRuns();

        thenNothingPropagated();
        thenStaleMessagesPurged();
    }

    @Test
    public void containsStoreException() throws KuraStoreException {
        givenMessageStoreAvailable();
        givenPurgeFailingWith(new KuraStoreException("store failure"));

        whenTaskRuns();

        thenNothingPropagated();
    }

    @Test
    public void containsRuntimeException() throws KuraStoreException {
        givenMessageStoreAvailable();
        givenPurgeFailingWith(new IllegalStateException("unexpected failure"));

        whenTaskRuns();

        thenNothingPropagated();
    }

    @Test
    public void containsLinkageError() throws KuraStoreException {
        givenMessageStoreAvailable();
        givenPurgeFailingWith(new NoClassDefFoundError("uninstalled bundle class"));

        whenTaskRuns();

        thenNothingPropagated();
    }

    @Test
    public void propagatesVirtualMachineError() throws KuraStoreException {
        givenMessageStoreAvailable();
        givenPurgeFailingWith(new OutOfMemoryError("simulated"));

        whenTaskRuns();

        thenPropagated(OutOfMemoryError.class);
    }

    /*
     * Steps
     */

    private void givenMessageStoreAvailable() throws KuraStoreException {
        when(this.storeState.getOrOpenMessageStore()).thenReturn(this.messageStore);
    }

    private void givenPurgeFailingWith(Throwable failure) throws KuraStoreException {
        doThrow(failure).when(this.messageStore).deleteStaleMessages(PURGE_AGE);
    }

    private void whenTaskRuns() {
        try {
            this.task.run();
        } catch (Throwable e) {
            this.propagatedThrowable = e;
        }
    }

    private void thenNothingPropagated() {
        assertNull(this.propagatedThrowable);
    }

    private void thenPropagated(Class<? extends Throwable> expected) {
        assertTrue("unexpected: " + this.propagatedThrowable, expected.isInstance(this.propagatedThrowable));
    }

    private void thenStaleMessagesPurged() throws KuraStoreException {
        verify(this.messageStore).deleteStaleMessages(PURGE_AGE);
    }
}
